const artworkByCategory = Object.freeze({
  "consumer-electronics": Object.freeze({
    file: "hardware-electronics.svg",
    alt: "Illustrative consumer electronics category artwork; not a product photograph."
  }),
  appliances: Object.freeze({
    file: "hardware-appliances.svg",
    alt: "Illustrative appliances category artwork; not a product photograph."
  }),
  "electrical-power": Object.freeze({
    file: "hardware-electrical.svg",
    alt: "Illustrative electrical equipment category artwork; not a product photograph."
  }),
  computers: Object.freeze({
    file: "hardware-computers.svg",
    alt: "Illustrative computer technology category artwork; not a product photograph."
  }),
  "solar-energy": Object.freeze({
    file: "hardware-energy.svg",
    alt: "Illustrative solar and energy category artwork; not a product photograph."
  })
});

function getSourceProductCategory(model, sourceCategory, description) {
  const type = sourceCategory.toLocaleLowerCase();
  const modelCode = model.toLocaleLowerCase();
  const productText = `${type} ${modelCode} ${description.toLocaleLowerCase()}`;
  const consumerElectronicsTypes = [
    "tv",
    "television",
    "soundbar",
    "sound bar",
    "audio",
    "speaker",
    "hifi",
    "theatre",
    "theater",
    "digitalboard",
    "qled",
    "oled",
    "uhd",
    "nano",
    "qned",
    "allinone",
    "avreciever",
    "portablebluetooth"
  ];

  if (type.includes("monitor")) return "computers";
  if (type.includes("solar") || type.includes("battery") || /^inv\d/.test(modelCode) || /^bat/.test(modelCode)) {
    return "solar-energy";
  }
  if (/\b(generator|ups|extension|surge|voltage protector)\b/.test(productText)) return "electrical-power";
  if (consumerElectronicsTypes.some((term) => type.includes(term))
    || type === "led"
    || (/(?:bracket|stand)/.test(`${type} ${modelCode}`) && /\btv\b/i.test(description))) {
    return "consumer-electronics";
  }
  return "appliances";
}

window.ElectronyHardwareSourceProducts = Object.freeze(sourceProducts.map(([brand, model, description, , sourceCategory, document, page, warranty]) => {
  const category = getSourceProductCategory(model, sourceCategory, description);
  const artwork = artworkByCategory[category];
  return Object.freeze({
    id: `${brand.toLocaleLowerCase()}-${model.toLocaleLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")}`,
    name: `${sourceCategory} ${model}`,
    brand,
    model,
    sku: model,
    category,
    description,
    specifications: Object.freeze(description.split(/[,;]+/).map((value) => value.trim()).filter(Boolean)),
    image: Object.freeze({ url: `../assets/catalogue/${artwork.file}`, alt: artwork.alt }),
    warranty,
    sourceCategory,
    source: Object.freeze({ document, page })
  });
}));
